package com.singtel.platformcommon;
import org.springframework.context.annotation.*;import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.web.SecurityFilterChain;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationConverter;import org.springframework.security.oauth2.server.resource.authentication.JwtGrantedAuthoritiesConverter;import org.springframework.security.oauth2.jwt.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.oauth2.core.*;
@Configuration @EnableMethodSecurity public class Security {
 @Bean @Profile("production") JwtDecoder decoder(@Value("${spring.security.oauth2.resourceserver.jwt.issuer-uri}")String issuer,@Value("${platform.audience}")String audience){NimbusJwtDecoder d=JwtDecoders.fromIssuerLocation(issuer);d.setJwtValidator(new DelegatingOAuth2TokenValidator<>(JwtValidators.createDefaultWithIssuer(issuer),token->token.getAudience().contains(audience)?OAuth2TokenValidatorResult.success():OAuth2TokenValidatorResult.failure(new OAuth2Error("invalid_token","Audience mismatch",null))));return d;}
 @Bean @Profile("production") SecurityFilterChain secure(HttpSecurity http)throws Exception{var granted=new JwtGrantedAuthoritiesConverter();granted.setAuthoritiesClaimName("roles");granted.setAuthorityPrefix("ROLE_");var converter=new JwtAuthenticationConverter();converter.setJwtGrantedAuthoritiesConverter(granted);return http.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(org.springframework.security.config.http.SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/actuator/health/**").permitAll().requestMatchers("/actuator/**").hasRole("ADMIN").anyRequest().authenticated()).oauth2ResourceServer(o->o.jwt(j->j.jwtAuthenticationConverter(converter))).build();}
 @Bean @Profile("local") SecurityFilterChain local(HttpSecurity http)throws Exception{return http.csrf(c->c.disable()).authorizeHttpRequests(a->a.anyRequest().permitAll()).build();}
}
